+    assert body_value(tmp_path,'''function add(){
+      let key="outer";{let key="inner";}
+      $.ajax({url:"/books",type:"POST",data:{key:key}});
+    }''')=='outer'
+
+
+def test_unknown_mutator_invalidates_object_values(tmp_path):
