            left, right = dict(target), dict(target)
            visit(yes, left)
            visit(no, right)
            for key in left.keys() | right.keys():
                fallback = 'undefined'
                if track_dom and key.startswith('@dom|'):
                    _,method,control = key.split('|',2)
                    fallback = '$('+json.dumps(control)+').'+method+'()'
                a, b = left.get(key, fallback), right.get(key, fallback)
                target[key] = a if a == b else '(' + condition + '?(' + a + '):(' + b + '))'
